-- Reuse the middle button as a context-sensitive gesture. Floating windows
-- move exactly like SUPER+LMB. On tiled windows, directional drags of at least
-- 80 logical pixels navigate tabs (left/right), restore a closed tab (up), or
-- close the current tab (down). One short click remains Ctrl+LMB; two short
-- clicks on the same tiled window toggle fake fullscreen like SUPER+F.
local middleSwipeDistance = 80
local middleClickMoveTolerance = 8
local middleDoubleClickTimeout = 400
local dragFloatingWindow = hl.dsp.window.drag()
local floatingMiddleDragActive = false
local tiledMiddleGesture
local pendingTiledMiddleClick
local pendingTiledMiddleClickTimer

local function sendSyntheticTap(mods, key, window)
    for _, state in ipairs({ "down", "up" }) do
        hl.dispatch(hl.dsp.send_key_state({
            mods   = mods,
            key    = key,
            state  = state,
            window = window,
        }))
    end
end

local function sendPendingTiledMiddleClick()
    local click = pendingTiledMiddleClick
    pendingTiledMiddleClick = nil
    pendingTiledMiddleClickTimer = nil
    if click then
        sendSyntheticTap("CTRL", "mouse:272", click.window)
    end
end

local function handleTiledMiddleClick(gesture)
    local pending = pendingTiledMiddleClick
    if pending and tostring(pending.window.stable_id) == tostring(gesture.window.stable_id) then
        pendingTiledMiddleClickTimer:set_enabled(false)
        pendingTiledMiddleClick = nil
        pendingTiledMiddleClickTimer = nil
        toggleFakeFullscreen(gesture.window)
        return
    end

    if pending then
        pendingTiledMiddleClickTimer:set_enabled(false)
        sendPendingTiledMiddleClick()
    end

    pendingTiledMiddleClick = gesture
    pendingTiledMiddleClickTimer = hl.timer(sendPendingTiledMiddleClick, {
        timeout = middleDoubleClickTimeout,
        type    = "oneshot",
    })
end

-- The floating dispatcher asks Hyprland to call this bind again on release so
-- it can end the compositor-owned window drag. Tiled releases are handled by
-- the separate release bind below.
local function handleMiddlePressOrFloatingRelease()
    if floatingMiddleDragActive then
        hl.dispatch(dragFloatingWindow)
        floatingMiddleDragActive = false
        return
    end

    local w = hl.get_active_window()
    if not w then return end

    if w.floating then
        floatingMiddleDragActive = true
        hl.dispatch(dragFloatingWindow)
        return
    end

    local cursor = hl.get_cursor_pos()
    if not cursor then return end
    tiledMiddleGesture = {
        window = w,
        x      = cursor.x,
        y      = cursor.y,
    }
end

local function finishTiledMiddleGesture()
    local gesture = tiledMiddleGesture
    tiledMiddleGesture = nil
    if not gesture then return end

    local cursor = hl.get_cursor_pos()
    if not cursor then return end

    local dx = cursor.x - gesture.x
    local dy = cursor.y - gesture.y
    local absDx = math.abs(dx)
    local absDy = math.abs(dy)
    if absDx <= middleClickMoveTolerance and absDy <= middleClickMoveTolerance then
        handleTiledMiddleClick(gesture)
    elseif math.max(absDx, absDy) < middleSwipeDistance then
        sendSyntheticTap("CTRL", "mouse:272", gesture.window)
    elseif absDx > absDy then
        if dx < 0 then
            sendSyntheticTap("CTRL + SHIFT", "Tab", gesture.window)
        else
            sendSyntheticTap("CTRL", "Tab", gesture.window)
        end
    elseif dy < 0 then
        sendSyntheticTap("CTRL + SHIFT", "T", gesture.window)
    else
        sendSyntheticTap("CTRL", "W", gesture.window)
    end
end

bind("mouse:274", handleMiddlePressOrFloatingRelease, "마우스 · 플로팅 창 이동/타일 창 Ctrl+클릭·탭 제스처·더블클릭 전체화면")
hl.bind("mouse:274", finishTiledMiddleGesture, { release = true })

