-- See https://wiki.hypr.land/Configuring/Basics/Window-Rules/
-- and https://wiki.hypr.land/Configuring/Basics/Workspace-Rules/

-- Example window rules that are useful

hl.window_rule({
    name  = "style-scratchpad",
    match = { workspace = scratchpadWorkspace },

    -- Keep the regular workspace behind the scratchpad sharp and visible.
    no_blur = true,
    opacity = "0.90 override 0.82 override 0.90 override",
})

hl.window_rule({
    name  = "style-scratchpad-terminal",
    match = {
        workspace = scratchpadWorkspace,
        class     = "^scratchpad-terminal$",
    },

    -- Kitty makes only its background translucent, keeping text fully opaque.
    opacity = "1.0 override 1.0 override 1.0 override",
})

local suppressMaximizeRule = hl.window_rule({
    -- Ignore maximize requests from all apps. You'll probably like this.
    name  = "suppress-maximize-events",
    match = { class = ".*" },

    suppress_event = "maximize",
})
-- suppressMaximizeRule:set_enabled(false)

hl.window_rule({
    -- Fix some dragging issues with XWayland
    name  = "fix-xwayland-drags",
    match = {
        class      = "^$",
        title      = "^$",
        xwayland   = true,
        float      = true,
        fullscreen = false,
        pin        = false,
    },

    no_focus = true,
})

-- virt-manager's SPICE console grabs the keyboard through GTK, which on Wayland
-- means zwp_keyboard_shortcuts_inhibit. While that inhibitor is up Hyprland stops
-- handling *every* keybind and hands the raw keys to the guest, so SUPER + <key>
-- lands in Windows instead of here. The Windows guest has no use for them, so
-- refuse the inhibitor for this window and keep SUPER host-side. Combined with the
-- bare Super_L bind above, the guest never sees the key at all.
hl.window_rule({
    name  = "vm-console-keeps-host-shortcuts",
    match = { class = "^virt-manager$" },

    no_shortcuts_inhibit = true,
})

-- Keep the CertMind phone emulator available without reflowing tiled windows.
-- The size follows the monitor height, while the phone stays tucked against the
-- right edge and pinned across workspaces. Match the main AVD window only; the
-- narrow Emulator toolbar remains an ordinary companion window.
hl.window_rule({
    name = "certmind-emulator-sticky",
    match = {
        class = "^Emulator$",
        title = "^Android Emulator - certmind_api_36:[0-9]+$",
    },

    float = true,
    pin   = true,
    size  = "620 monitor_h-80",
    move  = "monitor_w-w-40 40",
})

-- Layer rules also return a handle.
